const express = require\(''express''\);
const request = require\(''supertest''\);

// Mock the database modules
jest = require\(''jest''\);
const db = require\(''./src/models/db''\);
const EmployeeModel = require\(''./src/models/Employee''\);
const DepartmentModel = require\(''./src/models/Department''\);

jest.mock\(''./src/models/db'', \(\) => \({
  query: jest.fn\(\),
}\)\);

jest.mock\(''./src/models/Employee'', \(\) => \({
  findByManager: jest.fn\(\),
}\)\);

jest.mock\(''./src/models/Department'', \(\) => \({
  findAllActive: jest.fn\(\),
}\)\);

jest.mock\(''./src/utils/jwt'', \(\) => \({
  verifyToken: jest.fn\(\(token\) => {
    if \(token === ''hr-token''\) {
      return { id: ''hr-001'', employee_no: ''HR001'', email: ''hr@company.com'', role: ''hr'', department_id: ''dept-hr'' };
    }
    return null;
  }\),
  extractToken: jest.fn\(\(req\) => {
    const authHeader = req.headers && req.headers.authorization;
    if \(authHeader && authHeader.startsWith\(''Bearer ''\)\) {
      return authHeader.substring\(7\);
    }
    return null;
  }\),
}\)\);

const app = express\(\);
app.use\(express.json\(\)\);
app.use\(''/api/reports'', require\(''./src/routes/reports''\)\);
app.use\(\(err, req, res, next\) => {
  res.status\(err.status || 500\).json\({
    error: err.error || ''Internal Server Error'',
    message: err.message,
    code: err.code,
  }\);
}\);

db.query.mockResolvedValueOnce\({ rows: [{ leave_type: ''annual'', request_count: ''50'', total_days: ''120.5'', employee_count: ''20'' }] }\);
db.query.mockResolvedValueOnce\({ rows: [{ id: ''dept-1'', name: ''Tech'', request_count: ''30'', total_days: ''75.0'' }] }\);
db.query.mockResolvedValueOnce\({ rows: [] }\);
DepartmentModel.findAllActive.mockResolvedValueOnce\([{ id: ''dept-1'', name: ''Tech'' }]\);

request\(app\)
  .get\(''/api/reports/leave-utilization''\)
  .set\(''Authorization'', ''Bearer hr-token''\)
  .then\(res => {
    console.log\(''Status:'', res.status\);
    console.log\(''Body:'', JSON.stringify\(res.body, null, 2\)\);
  }\)
  .catch\(err => console.error\(''Error:'', err\)\);
")
